# Re-enable IPv6 on All Network Adapters Write-Host "Re-enabling IPv6 on all network adapters..." -ForegroundColor Cyan # Re-enable IPv6 globally Remove-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip6\Parameters" -Name "DisabledComponents" -ErrorAction SilentlyContinue # Re-enable IPv6 on each adapter $adapters = Get-NetAdapter | Where-Object { $_.Status -eq "Up" } foreach ($adapter in $adapters) { Enable-NetAdapterBinding -Name $adapter.Name -ComponentID ms_tcpip6 -ErrorAction SilentlyContinue Write-Host " Enabled IPv6 on: $($adapter.Name)" -ForegroundColor Gray } Write-Host "IPv6 has been re-enabled." -ForegroundColor Green Write-Host "A reboot is required for the global setting to take effect." -ForegroundColor Yellow